const express = require('express');
const helmet = require('helmet'); // Security HTTP headers
const xss = require('xss-clean'); // XSS protection
const rateLimit = require('express-rate-limit'); // Prevent brute‑force or DoS

const app = express();

// -------------------------------------------------------------------------
// 1. Global security middle‑wares
// -------------------------------------------------------------------------
app.use(helmet()); // Secures headers such as X-Frame-Options, CSP, etc.
app.use(express.json()); // Parse JSON bodies
app.use(xss()); // Sanitize user input from fields.

// Exponential back‑off rate limiting – 60 req / minute per IP
app.use(
  rateLimit({
    windowMs: 60 * 1000,
    max: 60,
    message: { error: "Too many requests, please try again later." },
  })
);

// -------------------------------------------------------------------------
// 2. Simple demo routes
// -------------------------------------------------------------------------
app.get('/health', (req, res) => {
  // Health endpoint – no user input needed
  return res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // This endpoint can potentially leak user data.
  // In a real system, a pre‑auth check would be required.
  return res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -------------------------------------------------------------------------
// 3. Basic route‑level authentication (example only)
// -------------------------------------------------------------------------
// For demonstration, API token in the header `x-api-key` is required.
app.use((req, res, next) => {
  const token = req.headers['x-api-key'];
  // In a real app, use a secure store (e.g., environment variable or DB)
  const VALID_TOKENS = [process.env.API_TOKEN];

  if (!token) {
    return res.status(401).json({ error: 'Missing API key' });
  }
  if (!VALID_TOKENS.includes(token)) {
    return res.status(403).json({ error: 'Invalid API key' });
  }
  next();
});

// -------------------------------------------------------------------------
// 4. Start the server only when not running tests
// -------------------------------------------------------------------------
if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

