const jwtSecret = process.env.JWT_SECRET;
const dbString = process.env.DB_CONNECTION_STRING;
```

**Notes**

* Keep `.env` out of version control (`.gitignore`).
* Guard against `undefined` values at startup:

  ```js
  if (!process.env.JWT_SECRET) {
    throw new Error('Missing JWT_SECRET in env');
  }
  ```

#### 2. Runtime secrets from a secrets manager

##### AWS Example – AWS Systems Manager Parameter Store

```bash
npm install aws-sdk
```

```js
const AWS = require('aws-sdk');
const ssm = new AWS.SSM({ region: process.env.AWS_REGION });

async function getSecret(name) {
  const result = await ssm.getParameter({
    Name: name,
    WithDecryption: true,
  }).promise();
  return result.Parameter.Value;
}

// Example usage
const [jwtSecret, dbString] = await Promise.all([
  getSecret('/myapp/jwt_secret'),
  getSecret('/myapp/db_connection_string'),
]);

// Now use jwtSecret / dbString in your app
```

##### GCP Example – Secret Manager

```bash
npm install @google-cloud/secret-manager
```

```js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function accessSecret(secretName) {
  const [version] = await client.accessSecretVersion({
    name: secretName, // e.g. projects/myproj/secrets/jwt_secret/versions/latest
  });
  const payload = version.payload.data.toString('utf8');
  return payload;
}
```

**Centralizing the fetch logic**

Create a small utility (`lib/secrets.js`):

```js
// lib/secrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function get(name) {
  const [version] = await client.accessSecretVersion({
    name,
  });
  return version.payload.data.toString('utf8');
}

module.exports = { get };
```

Then in your main app:

```js
const { get: secret } = require('./lib/secrets');

async function init() {
  const jwtSecret = await secret('projects/${GOOGLE_PROJECT_ID}/secrets/jwt_secret/versions/latest');
  // …
}
init();
```

