/* app.js – Hardened -->
 * All hardening recommendations are enabled – delete what you don't need.
 */

const express      = require('express');
const helmet       = require('helmet');
const cors         = require('cors');
const morgan       = require('morgan');
const rateLimit    = require('express-rate-limit');
const fs           = require('fs');
const path         = require('path');

const app = express();

const PORT        = process.env.PORT || 3000;
const AUTH_TOKEN  = process.env.AUTH_TOKEN || 'dev-secret';

// -- Security Middle‑ware -----------------------------------------------

app.use(helmet());                     // For XSS, clickjacking, etc.
app.use(cors({ origin: 'https://trusted.example.com' })); // Trust‑only
app.use(rateLimit({                   // Rate limiter
  windowMs: 15 * 60 * 1000,           // 15 minutes
  max: 200,                            // max 200 req / IP
  message: 'Too many requests – try again later.'
}));

// Request logging (write to file for audit)
const stream = fs.createWriteStream(
  path.join(__dirname, 'access.log'), { flags: 'a' }
);
app.use(morgan('common', { stream }));

// Simple authentication – optional for now
app.use((req, res, next) => {
  if (!req.path.startsWith('/health')) {               // secure all but health
    const token = req.headers.authorization?.split(' ')[1];
    if (token !== AUTH_TOKEN) {
      return res.status(401).json({ msg: 'Unauthorized' });
    }
  }
  next();
});

// Disable ETag header to avoid caching fixed responses
app.disable('etag');

// -- Routes -------------------------------------------------------------

app.get('/health', (req, res) => {
  // Return time only if you really need it
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Future: fetch from DB, validate id etc.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -- Error handler -----------------------------------------------------

app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ msg: 'Internal Server Error' });
});

// -- Server -------------------------------------------------------------

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

> **What changed?**  
> * Added **helmet**, **cors**, **rate‑limiting** & **request logging**.  
> * Included a simple Bearer‑token **authentication** guard.  
> * Recommended error handling and request validation placeholders.  

