### c) `config/secrets.js`

```js
// config/secrets.js
const dotenv = require('dotenv-safe');
dotenv.config({ example: '.env.template' });  // loads .env, verifies required keys

module.exports = {
  PORT: parseInt(process.env.PORT, 10) || 3000,
  AUTH_TOKEN: process.env.AUTH_TOKEN,
  // add more secrets as needed
};
```

### d) Refactor `app.js` to use the new config

```js
// app.js
const express  = require('express');
const helmet   = require('helmet');
const cors     = require('cors');
const { PORT, AUTH_TOKEN } = require('./config/secrets');

const app = express();

// ... all the middleware, routes from the hardened example ...

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
