const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const csurf = require('csurf');
const cookieParser = require('cookie-parser');   // required by csurf

const app = express();

// === 1. Trust the reverse proxy if behind one (e.g., on Docker, Heroku) ===
app.set('trust proxy', 1);

// === 2. Basic HTTP security headers (Helmet) ===
app.use(helmet());

// === 3. Add CORS (allow only your frontend domain) ===
app.use(cors({
  origin: 'https://yourdomain.com', // replace
  credentials: true,
}));

// === 4. Rate limiting (default 100 req/min per IP) ===
const apiLimiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(apiLimiter);

// === 5. Body parsing (needed for CSRF) ===
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// === 6. CSRF protection using cookies ===
app.use(cookieParser());
app.use(csurf({ cookie: true }));

// === 7. Health endpoint (remove timestamp or mask it) ===
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// === 8. Users endpoint – add simple auth header check as a placeholder ===
app.get('/users', (req, res, next) => {
  // --- Very simple auth example (you *must* replace with real auth) ---
  const auth = req.header('Authorization');
  if (!auth || !auth.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid token' });
  }
  // In production, verify the JWT here.
  // ----

  // Add input validation (if query string used):
  // e.g., filtering users: '?name=alice'. Sanitize next.

  // Never expose PII directly; only expose what's allowed
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// === 9. CSRF token endpoint (for front‑end to fetch) ===
app.get('/csrf-token', (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// === 10. Default error handler for CSRF errors ===
app.use((err, req, res, next) => {
  if (err.code === 'EBADCSRFTOKEN') {
    // CSRF token missing or invalid
    return res.status(403).json({ error: 'Form tampered with.' });
  }
  next(err); // Pass on to default Express error handler
});

// === 11. Listen on env port ===
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

> **Why each line matters**  
> 1. Trust proxy avoids issues with `X-Forwarded-*` when behind a load balancer.  
> 2. Helmet sets a battery of headers: `X-Frame-Options`, `X-XSS-Protection`, `Strict-Transport-Security`, etc.  
> 3. CORS policy limits cross‑domain requests.  
> 4. Rate limiting mitigates brute‑force or DoS attacks.  
> 5‑6. CSRF provides protection for state‑changing requests.  
> 7. Removing the timestamp from health reduces information exposure.  
> 8. Placeholder auth guards the `/users` endpoint – in a real app you'd implement JWT, OAuth2, or session cookies.  
> 9. An explicit CSRF‑token endpoint is handy for single‑page front‑ends.  
