## 2. Implement Proper Authentication & Authorization (A2, A5)

> **In the current state, nothing is protected.**  If you later introduce a `POST /users` that creates accounts or a `/profile` route that shows personal info, the API will expose that data to everyone.

### Suggested Flow

1. **Choose a strategy**  
   *JWT* (stateless) or *sessions + cookies* (stateful).  
   For REST APIs *JWT* is often simpler.

2. **Add a login endpoint** that validates credentials and signs a JSON Web Token.

3. **Create middleware** `requireAuth` that verifies the token.

4. **Protect routes** that return sensitive data.

```js
const jwt = require('jsonwebtoken');
const { authSecret } = require('./config');

// ----- Helper -----
function signToken(payload) {
  return jwt.sign(payload, authSecret, { expiresIn: '1h' });
}

function verifyToken(token) {
  return jwt.verify(token, authSecret);
}

// ----- Login route (example) -----
app.post('/login', express.json(), (req, res) => {
  const { username, password } = req.body;
  // TODO: validate credentials (e.g., lookup in DB)
  if (username === 'admin' && password === 'Pa$$w0rd!') {
    const token = signToken({ sub: username, role: 'admin' });
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

// ----- Auth middleware -----
function requireAuth(req, res, next) {
  const auth = req.headers['authorization'];
  if (!auth) return res.status(401).json({ error: 'Missing token' });

  const token = auth.split(' ')[1]; // Bearer <token>
  try {
    req.user = verifyToken(token);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

**Protect a route:**

```js
// /users now returns only for authenticated users 
app.get('/users', requireAuth, (req, res) => {
  if (req.user.role !== 'admin')
    return res.status(403).json({ error: 'Forbidden' });

  res.json([
    { id: 1, name: 'Alice' },          // hide emails
    { id: 2, name: 'Bob' },
  ]);
});
```

