  // Adjust directives to your real front‑end
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"], // remove 'unsafe-inline' in prod
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));

/* ------------------------------------------------------------------
   2️⃣ CORS – allow only whitelisted origins
   ------------------------------------------------------------------ */
app.use(cors({
  origin: ['https://your‑client‑app.com', 'https://admin.your‑domain.com'],
  credentials: true,
}));

/* ------------------------------------------------------------------
   3️⃣ Rate limiting – protect against DoS / brute‑force
   ------------------------------------------------------------------ */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 minutes
  max: 200,                   // limit each IP to 200 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

/* ------------------------------------------------------------------
   4️⃣ Body parser – JSON only, size limit
   ------------------------------------------------------------------ */
app.use(json({ limit: '1mb' })); // protect against large payloads

/* ------------------------------------------------------------------
   5️⃣ Health‑check – no sensitive data
   ------------------------------------------------------------------ */
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/* ------------------------------------------------------------------
   6️⃣ Basic auth‑middleware (JWT example)
   ------------------------------------------------------------------ */
// in cookie or Authorization header?
// (clients will transmit `Authorization: Bearer <token>`)
function authRequired(req, res, next) {
  const authHeader = req.get('Authorization');
  if (!authHeader) return res.status(401).json({ message: 'Missing auth header' });

  const [type, token] = authHeader.split(' ');
  if (type !== 'Bearer' || !token) return res.status(401).json({ message: 'Invalid auth header' });

  try {
    // throws if token is invalid or expired
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload;      // let downstream route handlers use `req.user`
    next();
  } catch (err) {
    return res.status(401).json({ message: 'Invalid token' });
  }
}

/* ------------------------------------------------------------------
   7️⃣ “Users” – expose only what you really want
   ------------------------------------------------------------------ */
const secrets = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' }
];

app.get('/users', authRequired, (req, res) => {
  // Example of pagination + kludge: limit output to 10 results
  const page   = parseInt(req.query.page, 10) || 1;
  const limit  = Math.min(parseInt(req.query.limit, 10) || 20, 100);

  const startIdx = (page - 1) * limit;
  const data = secrets
    .slice(startIdx, startIdx + limit)
    .map(u => ({ id: u.id, name: u.name, email: u.email })) // hide internal fields
    ;

  res.json({ count: data.length, users: data, page, limit });
});

/* ------------------------------------------------------------------
   8️⃣ 404 & generic error handler
   ------------------------------------------------------------------ */
