```js
const jwt = require('jsonwebtoken');

const SECRET_KEY = process.env.JWT_SECRET || 'change-me-in-prod'; // never hard‑code secret

function authenticate(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = auth.split(' ')[1];
  jwt.verify(token, SECRET_KEY, (err, payload) => {
    if (err) return res.status(401).json({ error: 'Invalid token' });
    req.user = payload; // attach to request object
    next();
  });
}

// Protect /users with auth
app.get('/users', authenticate, (req, res) => {
  // you can filter based on req.user if needed
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

If you don’t want to expose real user data, consider returning sanitized data or add permission checks.

