```js
// app.js

/**
 *  Simple secure Express server – example only
 *  Adopt these patterns before moving to production.
 */

const express = require('express')
const helmet  = require('helmet')
const rateLimit = require('express-rate-limit')
const cors = require('cors')
const morgan = require('morgan')
const jwt = require('jsonwebtoken')

// ---------- 1️⃣ ENVIRONMENT / SECRET CONFIG ----------
require('dotenv').config()          // Use .env for secrets
const PORT = process.env.PORT || 3000
const JWT_SECRET = process.env.JWT_SECRET || 'super‑secret‑change‑me'

// ---------- 2️⃣ APP FACTORY ----------
const app = express()

// ---------- 3️⃣ SECURITY MIDDLEWARE ----------
app.use(helmet({
  contentSecurityPolicy: false,          // Disable CSP for dev, enable in prod
  referrerPolicy: { policy: 'no-referrer' },
}))
app.disable('x-powered-by')             // Remove Express banner

// Rate limit – 100 requests / hour per IP
app.use(rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 100,
  handler: (_, __, res) => res.status(429).json({error: 'Too many requests'}),
}))

// CORS – allow only specified origins (example: http://localhost:3000)
app.use(cors({
  origin: ['http://localhost:3000', 'https://my‑app.com'],
  credentials: true,   // Allow cookies if using them
}))

// Request logging (combined) – useful for audit
app.use(morgan('combined'))

// ---------- 4️⃣ AUTHENTICATION MIDDLEWARE ----------
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization
  if (!authHeader) return res.status(401).json({error: 'Missing token'})

  const token = authHeader.split(' ')[1]
  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({error: 'Invalid token'})
    req.user = user
    next()
  })
}

// ---------- 5️⃣ ROUTES ----------
app.get('/health', (_, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() })
})

// Public data – consider limiting or removing sensitive fields
app.get('/users', (req, res) => {
  // In prod fetch from DB with a query‑builder that parameterises inputs
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]

  // Mask emails for anonymous requests
  const sanitized = req.user
    ? users
    : users.map(({email, ...rest}) => rest)

  res.json(sanitized)
})

/**
 * API protected with JWT – add more routes under /api
 */
app.use('/api', authenticateJWT, (router) => {
  // Example resource that requires authentication:
  router.get('/dashboard', (req, res) => {
    res.json({ msg: `Welcome ${req.user.sub}` })
  })
})

// ---------- 6️⃣ START ----------
app.listen(PORT, () => {
  console.log(`👩‍💻 Server listening on port ${PORT}`)
})

module.exports = app
```

