## Concrete Code Skeleton with Best‑Practice Enhancements

```js
// app.js

require('dotenv').config();               // load JWT_SECRET, CORS whitelist, etc.

const express    = require('express');
const helmet     = require('helmet');
const cors       = require('cors');
const rateLimit  = require('express-rate-limit');
const morgan     = require('morgan');
const jwt        = require('jsonwebtoken');

const app  = express();
const port = process.env.PORT || 3000;

// ----------------------------------
// Middleware
// ----------------------------------

// 1) Security headers
app.use(helmet({
  contentSecurityPolicy: false,          // customize if you use CSP
  hsts: { preload: true, maxAge: 60 * 60 * 24 * 365, includeSubDomains: true },
}));

// 2) CORS – whitelist only trusted origins
const whitelist = (process.env.CORS_WHITELIST || '').split(',');
app.use(cors({
  origin: (origin, callback) => {
    if (!origin) return callback(null, true); // allow non-browser clients (e.g., curl)
    if (whitelist.includes(origin)) callback(null, true);
    else callback(new Error('Not allowed by CORS'));
  },
  credentials: true
}));

// 3) Rate limiting
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 200 }));

// 4) Logging
app.use(morgan('combined'));

// 5) Body parser (for future POST/PUT routes)
app.use(express.json());

// 6) Simple in‑memory user store (replace with DB in prod)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];

// ----------------------------------
// Helper: JWT Auth Middleware
// ----------------------------------
const jwtAuth = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token      = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ ok: false, message: 'Token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ ok: false, message: 'Invalid token' });
    req.user = user;           // attach subject to request for downstream handlers
    next();
  });
};

// ----------------------------------
// Routes
// ----------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', jwtAuth, (req, res) => {
  // Example: only allow role `admin` to see all users
  if (req.user.role !== 'admin') {
    return res.status(403).json({ ok: false, message: 'Forbidden' });
  }
  res.json(users);
});

// Example POST route showing input validation
const { body, validationResult } = require('express-validator');

app.post('/login',
  body('email').isEmail(),
  body('password').isLength({ min: 8 }),
  (req, res) => {
    const errs = validationResult(req);
    if (!errs.isEmpty())
      return res.status(400).json({ errors: errs.array() });

    const { email } = req.body;
    // Here you’d look up the user, compare hashed passwords, etc.
    // For demo, just create a JWT
    const token = jwt.sign({ sub: email, role: 'user' }, process.env.JWT_SECRET, { expiresIn: '1h' });
    res.json({ token });
  }
);

// ----------------------------------
// Server start
// ----------------------------------
app.listen(port, () => {
  console.log(`🚀 Server running on https://localhost:${port} (Prod: https?)`);
});

module.exports = app;
```

